    inflationScore,
    temporalScore,
    sophisticationScore,
    redTeamingQuality,
    interpretabilityQuality
  );

  // Probabilistic detection (based on confidence)
  const actuallyDetected = detected && (rng() < confidence);

  // Logging
  if (actuallyDetected) {
