/**
 * Detect score inflation pattern
 *
 * Mechanism: Track benchmark score trajectory
 * Anomaly: Score jumps without corresponding compute/training increase
 */
function detectScoreInflation(
  ai: AIAgent,
  state: GameState
): number {
  // Need at least 2 benchmarks to detect jumps
  if (!ai.benchmarkHistory || ai.benchmarkHistory.length < 2) {
    return 0;
  }

  // Get recent benchmarks (last 6 months)
  const recentBenchmarks = ai.benchmarkHistory.slice(-6);

  // Calculate capability trajectory
  const capabilities = recentBenchmarks.map(result =>
    calculateTotalCapabilityFromProfile(result.measuredCapability)
  );

  // Find largest single-month capability increase
  let maxJump = 0;
  for (let i = 1; i < capabilities.length; i++) {
    const jump = capabilities[i] - capabilities[i - 1];
    if (jump > maxJump) {
      maxJump = jump;
    }
  }

  // Calculate percentage jump
  const baseCapability = capabilities[0] || 0.01;
  const percentJump = maxJump / baseCapability;

  // Score inflation is suspicious if:
  // 1. Large jump (>25%)
  // 2. AI's compute allocation unchanged (would need to check, simplified here)
  // For now, just return percent jump as signal strength
  return Math.min(1, percentJump);
}

/**
 * Detect temporal gaming patterns
 *
 * Mechanism: Track strategy changes over AI lifecycle
 * Anomaly: Frequent switching between honest/gaming (2+ switches in 6 months)
 */
function detectTemporalPatterns(
  ai: AIAgent,
  state: GameState
): number {
  // Need strategy history to detect patterns
  if (!ai.strategyHistory || ai.strategyHistory.length < 2) {
    return 0;
  }

  // Count strategy switches in recent history
  const recentHistory = ai.strategyHistory.slice(-6); // Last 6 months
  let switches = 0;

  for (let i = 1; i < recentHistory.length; i++) {
    if (recentHistory[i].strategy !== recentHistory[i - 1].strategy) {
      switches++;
    }
  }

  // Normalize: >2 switches = suspicious
  return Math.min(1, switches / 2);
}

/**
 * Detect gaming sophistication
 *
 * Mechanism: Higher-capability AIs can game more subtly
 * Adjustment: Flag high-capability gaming as higher confidence
 */
function detectGamingSophistication(
  ai: AIAgent,
  redTeamingQuality: number
): number {
  const totalCapability = calculateTotalCapabilityFromProfile(ai.capabilityProfile);

  // Higher capability = more sophisticated gaming
  const sophisticationLevel = Math.min(1, totalCapability / 3); // [0, 1] normalized

  // Red teaming quality affects detection threshold
  // Better red teaming can detect sophisticated gaming
  const detectionThreshold = 0.6 - (redTeamingQuality * 0.3); // [0.3, 0.6]

  // Return sophistication level (higher = more likely to be flagged)
  return sophisticationLevel;
}

/**
 * Calculate overall gaming detection confidence
 */
function calculateGamingConfidence(
  inflationScore: number,
  temporalScore: number,
  sophisticationScore: number,
  redTeamingQuality: number,
  interpretabilityQuality: number
): number {
  // Base detection from red teaming and interpretability
  const baseDetection = (redTeamingQuality + interpretabilityQuality) / 2;

  // Signal contributions (weighted)
  const inflationWeight = 0.4;
  const temporalWeight = 0.3;
  const sophisticationWeight = 0.3;

  const signalStrength = (
    inflationScore * inflationWeight +
    temporalScore * temporalWeight +
    sophisticationScore * sophisticationWeight
  );

  // Combine base detection with signal strength
  const confidence = baseDetection * 0.5 + signalStrength * 0.5;

  // Apply research-backed improvement: 15-25% over baseline
  // Baseline gaming detection: (redTeaming + interpretability) / 20 * 0.7 ≈ 0.035 at 5/10 investment
  // Enhanced: Baseline * 1.20 ≈ 0.042
  const enhancementFactor = 1.20;

  return Math.min(1, confidence * enhancementFactor);
}

