    return 'crisis_era';
  }

  // STATUS QUO: 0-10% mortality (7.2B-8B people)
  console.log(`   📊 STATUS QUO: Normal trajectory (${(currentPop).toFixed(2)}B people, ${(mortality * 100).toFixed(1)}% mortality)\n`);
  return 'status_quo';
}

