/**
 * TIER 2 Phase 2C-E: Ensemble Meta-Learning Phase
 *
 * Updates ensemble detection weights based on historical accuracy
 * Runs every 5-6 months (conservative estimate)
 *
 * Research Foundation:
 * - Meta Invariance Defense (2024): MAML for adversarial robustness
 * - Adapts in 15-25 examples (extrapolated to 50 evaluations / 5-6 months)
 *
 * Expected Improvement: +8-12% detection rate after adaptation
 */

import { GameState, RNGFunction, SimulationPhase, PhaseContext, PhaseResult } from '@/types/game';
import { EnsembleWeights } from '../../ensembleDetection';

export const EnsembleMetaLearningPhase: SimulationPhase = {
  id: 'ensemble-meta-learning',
  name: 'Ensemble Meta-Learning',
  order: 36, // After most systems updates, before final metrics
  execute: (state: GameState, rng: RNGFunction, context: PhaseContext): PhaseResult => {
    const currentMonth = state.currentYear * 12 + state.currentMonth;
    const events = [];

    // Check if ensemble detection is enabled
    if (!state.government.ensembleDetection?.enabled) {
      return { state, events };
    }

    const meta = state.government.ensembleDetection.metaLearning;

this.orchestrator.registerPhase(new BenchmarkEvaluationsPhase());
this.orchestrator.registerPhase(new GamingDetectionPhase());  // TIER 2 Phase 3 (Oct 17, 2025)
this.orchestrator.registerPhase(new ProactiveSleeperDetectionPhase());  // TIER 2 Phase 4 (Oct 17, 2025)
this.orchestrator.registerPhase(EnsembleMetaLearningPhase);  // TIER 2 Phase 2C-E (Oct 20, 2025) - const object, not class
this.orchestrator.registerPhase(new CrisisPointsPhase());
this.orchestrator.registerPhase(new ExogenousShockPhase());  // Contingency & Agency Phase 2 (Oct 17, 2025)
this.orchestrator.registerPhase(new CriticalJuncturePhase());  // Contingency & Agency Phase 3 (Oct 17, 2025)

// Batch 4: Agent/Infrastructure phases (1.0 - 10.0)
this.orchestrator.registerPhase(new ComputeGrowthPhase());

